'use strict';
const IoTVisuals=(()=>{
const ic=n=>`<i class="ph ph-${n}" aria-hidden="true"></i>`;
const n=(id,x,y,label,icon,sub='',tone='')=>({id,x,y,label,icon,sub,tone});
const e=(from,to,type='wireless',flow=true,extra={})=>({from,to,type,flow,...extra});
function diagram(title,nodes,edges,regions=[],caption='Packets show a simplified data path; links can carry traffic both ways.'){
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const byId=Object.fromEntries(nodes.map(n=>[n.id,n]));
const lines=edges.map((l,i)=>{const a=byId[l.from],b=byId[l.to],d=l.path||`M ${a.x} ${a.y} L ${b.x} ${b.y}`;return `<path class="network-link ${l.type} ${l.broken?'broken':''}" d="${d}"/>${l.label?`<text class="network-link-label" x="${l.lx??(a.x+b.x)/2}" y="${l.ly??((a.y+b.y)/2-12)}" text-anchor="middle">${l.label}</text>`:''}${l.flow&&!l.broken&&!reduced?`<circle r="4" opacity="0" class="network-packet ${l.type}"><set attributeName="opacity" to="1" begin="${i*.3}s"/><animateMotion dur="${2.2+i*.25}s" begin="${i*.3}s" repeatCount="indefinite" path="${d}"/></circle>`:''}${l.broken?`<text class="network-cut" x="${(a.x+b.x)/2}" y="${(a.y+b.y)/2+5}" text-anchor="middle">×</text>`:''}`}).join('');
return `<figure class="network-figure"><div class="network-map" role="img" aria-label="${title}: ${nodes.map(x=>x.label+(x.sub?' ('+x.sub+')':'')).join(', ')}. ${edges.map(l=>byId[l.from].label+' to '+byId[l.to].label+' via '+l.type+(l.broken?', disconnected':'')).join('; ')}">${regions.map(r=>`<div class="network-region" style="left:${r.x/9}%;top:${r.y/3.1}%;width:${r.w/9}%;height:${r.h/3.1}%"><span>${r.label}</span></div>`).join('')}<svg class="network-wires" viewBox="0 0 900 310" preserveAspectRatio="none" aria-hidden="true">${lines}</svg>${nodes.map(x=>`<div class="network-node ${x.tone}" style="left:${x.x/9}%;top:${x.y/3.1}%"><div class="network-icon">${ic(x.icon)}</div><strong>${x.label}</strong>${x.sub?`<small>${x.sub}</small>`:''}</div>`).join('')}</div><div class="network-legend"><span class="legend-wireless">Radio link</span><span class="legend-wired">Wired link</span><span class="legend-backhaul">IP backhaul</span></div><figcaption>${caption}</figcaption></figure>`;
}
function connection(v){
const cloud=n('app',825,145,'Application','cloud','Uses the reading','purple');
if(v==='wifi')return diagram('Wi-Fi star network',[n('sensor',85,80,'Sensor','thermometer-simple','Wi-Fi'),n('camera',85,215,'Camera','video-camera','Wi-Fi'),n('ap',330,145,'AP / router','wifi-high','Home network'),n('internet',590,145,'Internet','globe','WAN connection','purple'),cloud],[e('sensor','ap'),e('camera','ap'),e('ap','internet','backhaul',true,{label:'WAN',ly:126}),e('internet','app','backhaul')],[{x:18,y:24,w:410,h:267,label:'LOCAL NETWORK'}]);
if(v==='ble')return diagram('Bluetooth LE peripheral to central',[n('sensor',100,85,'Wearable','watch','Peripheral'),n('other',100,215,'Sensor','thermometer-simple','Peripheral'),n('phone',425,145,'Phone','device-mobile','Central + local app'),n('internet',650,145,'Internet','globe','Optional','purple'),cloud],[e('sensor','phone'),e('other','phone'),e('phone','internet','backhaul',false,{label:'optional upload',ly:120}),e('internet','app','backhaul',false)],[{x:25,y:24,w:480,h:267,label:'BLUETOOTH LE CONNECTIONS'}],'The phone can use readings locally. Cloud upload is optional; Bluetooth LE also supports other topologies.');
if(v==='zigbee')return diagram('Zigbee mesh with IP gateway',[n('sensor',70,80,'Sensor','thermometer-simple','End device'),n('door',70,225,'Door sensor','door','End device'),n('r1',260,80,'Powered router','lightbulb','Relays data'),n('r2',260,225,'Powered router','plugs','Relays data'),n('hub',495,145,'Coordinator','graph','Hub / IP gateway'),n('internet',665,145,'IP network','globe','Backhaul','purple'),cloud],[e('sensor','r1'),e('door','r2'),e('r1','r2','wireless',false),e('r1','hub'),e('r2','hub'),e('hub','internet','backhaul'),e('internet','app','backhaul')],[{x:16,y:24,w:550,h:270,label:'ZIGBEE MESH'}],'Powered Zigbee routers can relay. Battery end devices do not relay. The coordinator and IP gateway are combined here.');
if(v==='lora')return diagram('LoRaWAN star of stars',[n('sensor',65,80,'Field sensor','plant','LoRa radio'),n('meter',65,220,'Water meter','drop','LoRa radio'),n('g1',275,80,'Gateway A','broadcast','Forwards packets'),n('g2',275,220,'Gateway B','broadcast','Forwards packets'),n('ns',580,145,'Network server','database','Filters duplicates','purple'),n('app',820,145,'Application server','cloud','Uses the reading','purple')],[e('sensor','g1'),e('sensor','g2','wireless',false),e('meter','g2'),e('meter','g1','wireless',false),e('g1','ns','backhaul',true,{label:'IP',lx:430,ly:98}),e('g2','ns','backhaul'),e('ns','app','backhaul')],[{x:12,y:22,w:347,h:271,label:'LoRa RADIO'},{x:498,y:70,w:387,h:150,label:'SERVER FUNCTIONS'}],'Nearby gateways may hear the same packet. Gateways forward it over IP; the network server removes duplicates.');
if(v==='cell')return diagram('Cellular network',[n('sensor',75,80,'Tracker','map-pin','Cellular modem'),n('meter',75,220,'Remote sensor','thermometer-simple','Cellular modem'),n('tower',285,145,'Base station','cell-tower','Radio access'),n('core',470,145,'Operator core','database','SIM / service','purple'),n('internet',650,145,'Internet','globe','','purple'),cloud],[e('sensor','tower'),e('meter','tower'),e('tower','core','backhaul'),e('core','internet','backhaul'),e('internet','app','backhaul')],[{x:210,y:34,w:336,h:237,label:'OPERATOR NETWORK'}]);
return diagram('Ethernet local area network',[n('sensor',70,80,'Sensor','thermometer-simple','Ethernet port'),n('camera',70,220,'Camera','video-camera','Ethernet port'),n('switch',295,145,'Switch','plugs-connected','Local network'),n('local',500,230,'Local server','desktop','LAN application'),n('router',500,80,'Router','arrows-left-right','WAN gateway'),n('internet',675,80,'Internet','globe','','purple'),n('app',835,80,'Cloud app','cloud','Optional','purple')],[e('sensor','switch','wired'),e('camera','switch','wired'),e('switch','local','wired'),e('switch','router','wired'),e('router','internet','backhaul'),e('internet','app','backhaul')],[{x:12,y:20,w:548,h:273,label:'WIRED LAN'}],'The switch joins local devices. A router provides a path to other networks; the local server works without the internet.');
}
function watering(on){return `<div class="watering-visual ${on?'water-on':'water-off'}" role="img" aria-label="${on?'Pump on: animated water flowing into the soil':'Pump off: water supply cut off, no water flows'}"><img src="assets/plant.png" alt="Smart pot with a soil sensor"><svg class="irrigation" viewBox="0 0 360 260" aria-hidden="true"><path class="water-pipe" d="M350 66 H285 Q255 66 255 88 V95"/><path class="pipe-inner" d="M350 66 H285 Q255 66 255 88 V95"/><path class="water-in-pipe" d="M350 66 H285 Q255 66 255 88 V95"/><path class="water-stream" d="M255 96 Q244 109 222 121"/><path class="water-droplet droplet-a" d="M248 101 Q251 106 248 109 Q245 106 248 101Z"/><path class="water-droplet droplet-b" d="M237 112 Q240 117 237 120 Q234 117 237 112Z"/><path class="water-splash" d="M220 122 l-8-5 M224 124 l9-8 M221 126 l-11 2"/><circle class="water-valve" cx="315" cy="66" r="10"/><path class="valve-handle" d="${on?'M309 66 H321':'M315 60 V72'}"/></svg><div class="water-state">${ic(on?'drop':'drop-slash')} Water ${on?'flowing':'stopped'}</div></div>`}
function mesh(relay){return diagram('Zigbee relay around a blocked direct path',[n('sensor',100,170,'Sensor','thermometer-simple','Battery end device'),n('relay',450,70,'Powered relay','plugs',relay?'Zigbee router':'Not installed',relay?'':'offline'),n('hub',800,170,'Coordinator','graph',relay?'Reading received':'Waiting for reading',relay?'':'offline')],[e('sensor','hub','wireless',false,{broken:true,label:'Direct link blocked',lx:450,ly:181}),e('sensor','relay','wireless',relay,{broken:!relay}),e('relay','hub','wireless',relay,{broken:!relay})],[],'A powered router supplies an alternate radio route. The end device remains a leaf node.');}
function range(wall){return diagram('Obstacle affecting a Bluetooth link',[n('sensor',155,150,'BLE sensor','bluetooth','Transmits a reading'),n('wall',450,150,wall?'Thick wall':'Clear space',wall?'wall':'wind',wall?'Weakens signal':'Radio path',wall?'amber':''),n('phone',745,150,'Phone','device-mobile',wall?'Reading missed':'Reading received',wall?'offline':'')],[e('sensor','phone','wireless',!wall,{broken:wall})],[],wall?'This illustrative wall blocks the link. Actual range depends on the radio, antenna and environment.':'A direct radio link joins the sensor and phone.');}
function bandwidth(video){return diagram('LoRaWAN data rate example',[n('device',85,145,video?'Camera':'Field sensor',video?'video-camera':'thermometer-simple',video?'Continuous video':'24.8°C message'),n('gateway',320,145,'Gateway','broadcast','LoRa radio'),n('server',585,145,'Network server','database','IP backhaul','purple'),n('app',820,145,'Application','cloud',video?'No video stream':'Reading received',video?'offline':'purple')],[e('device','gateway','wireless',!video,{broken:video}),e('gateway','server','backhaul',!video),e('server','app','backhaul',!video)],[],video?'LoRaWAN is not suitable for continuous video.':'A small sensor message crosses the radio link, then the IP backhaul.');}
function poe(on){return diagram('Power over Ethernet connection',[n('switch',170,145,on?'PoE switch':'Network switch','plugs-connected',on?'Compatible power source':'Data only'),n('camera',720,145,'IP camera','video-camera',on?'Power + data':'Needs power adapter',on?'':'offline')],[e('switch','camera','wired',true,{label:'Ethernet data',lx:445,ly:111}),...(on?[e('switch','camera','power',true,{path:'M170 165 L720 165',label:'PoE power',lx:445,ly:194})]:[])],[],on?'Both ends support compatible PoE. A single cable carries data and power.':'The Ethernet data link alone supplies no power.');}
function edge(local,online){return diagram('Local control versus cloud control',[n('sensor',90,190,'Door sensor','door','Input'),n('controller',390,190,'Local controller','cpu',local?'Makes decision':'Waits for cloud'),n('cloud',645,65,'Cloud service','cloud',online?'Internet available':'Internet disconnected',online?'purple':'offline'),n('lock',800,190,'Lock','lock-open',local||online?'Responds':'Waiting',local||online?'':'offline')],[e('sensor','controller','wired'),e('controller','cloud','backhaul',!local&&online,{broken:!online}),e('cloud','controller','backhaul',!local&&online,{broken:!online,path:'M645 85 Q560 160 390 210'}),e('controller','lock','wired',local||online)],[],local?'The local control path does not need an internet connection.':'This design requires the cloud decision to return before it actuates the lock.');}
return {connection,watering,mesh,range,bandwidth,poe,edge};
})();
